```javascript
function switchAdjectiveOrder(sentence) {
  const regex = /(([A-Z][a-z]*\s)?[A-Z][a-z]*(?:[,\.!\?]\s*)?(?:[a-z]+(?:[-\s][a-z]+)*|\w+(?:[-\s][a-z]+)*|[a-z]+(?:[-\s][a-z]+)*)(?:\s+[A-Z][a-z]*|$)/g; // eslint-disable-line
  let match, newSentence = '';

  while ((match = regex.exec(sentence)) !== null) {
    const word = match[0];
    const isLastWord = match.index === (regex.lastIndex - regex.exec(sentence)[0].length);
    const prevSpaceIndex = sentence.lastIndexOf(' ', match.index - 1);
    const prevWord = prevSpaceIndex >= 0 ? sentence.slice(prevSpaceIndex, match.index) : '';

    if (isLastWord || !isAdjective(word) || !prevWord) {
      newSentence += word;
      continue;
    }

    const nextWord = sentence.slice(match.index + word.length).match(/[A-Z][a-z]*/)[0];
    newSentence += nextWord;
    sentence = sentence.slice(0, match.index) + nextWord + ' ' + word;
  }

  return newSentence.trim() + ' ' + sentence.slice(regex.lastIndex);
}

function isAdjective(word) {
  // You can add more conditions based on your specific use case.
  // For simplicity, we check for words ending with "ly" as potential adjectives.
  return /([^sx]$)\b([A-Z][a-z]*ly)\b/.test(word);
}

