// subschema1.ts
import { Schema, Document } from 'mongoose';

export interface SubSchema1 extends Document {
  field1: string;
  field2: number;
}

export const SubSchema1Schema = new Schema<SubSchema1>({
  field1: { type: String, required: true },
  field2: { type: Number, required: true },
});

3. Now, create the main schema file where you will combine the sub-schemas using Mongoose's `add()` method. Let's call this file `mainSchema.ts`.

```typescript
// mainSchema.ts
import { Schema, Document, model } from 'mongoose';
import { SubSchema1Document } from './subschema1'; // Import the subschema interface

export interface MainDocument extends Document {
  subSchema1: SubSchema1Document;
  field3: string;
}

const MainSchema = new Schema<MainDocument>({
  subSchema1: { type: SubSchema1Schema, required: true },
  field3: { type: String, required: true },
});

MainSchema.add(SubSchema1Schema); // Add the subschema

export default model<MainDocument>('Main', MainSchema);
```

4. Use the `MainDocument` interface and the exported model in your services or controllers to perform CRUD operations on the combined schema document.

